/*
 * A108056  Numbers of the form (7^i)*(13^j).
 * https://oeis.org/A108056
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) is the n‑th smallest number of the form 7^i * 13^j (i,j≥0).
 *            * The sequence is generated by the classic humble‑number
 *            algorithm with the * two primes 7 and 13
 * Range:     u8 n <= 5, u16 n <= 18, u32 n <= 60, u64 n <= 217, u128 n <= 830,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)1;          /* offset is 1, n≥1 in practice */

    /* allocate array a[1..n] */
    seq_t *a = (seq_t *)malloc((n + 1) * sizeof(seq_t));
    if (!a)
        return (seq_t)0;          /* allocation failure – unlikely for n≤10000 */

    a[1] = (seq_t)1;
    idx_t i7  = 1;                /* next index for 7‑multiples                */
    idx_t i13 = 1;                /* next index for 13‑multiples               */

    for (idx_t k = 2; k <= n; ++k) {
        seq_t c7  = a[i7]  * (seq_t)7;
        seq_t c13 = a[i13] * (seq_t)13;
        seq_t nxt = (c7 < c13) ? c7 : c13;
        a[k] = nxt;

        if (nxt == c7)
            ++i7;
        if (nxt == c13)
            ++i13;
    }

    seq_t result = a[n];
    free(a);
    return result;
}
